//海口大碗

inherit ITEM;
inherit F_LIQUID;

void create() {
    set_name("海口大碗", ({ "wan", "bowl" }));
    set_weight(50);
    if (clonep())
        set_default_object(__FILE__);
    else {
        set("unit", "只");
        set("long", "这是一只可盛水的粗瓷大碗。\n");
        set("value", 0);
        set("max_liquid", 6);
    }

    // because a container can contain different liquid
    // we set it to contain tea at the beginning
    set("liquid", ([
        "type": "water",
        "name": "水",
        "remaining": 0,
        "drunk_apply": 0,
    ]));
}

