        me->set("water", me->query("water") / 2);
    }
}

int do_broadcast(string arg) {
    string type;
    string mesg;
    object me;

    me = this_player();

    if (query("order_owner") != me->query("id"))
        return 0;

    type = query("order_type");

    if (type == "marry") {
        mesg = me->name() + "现在在醉仙楼芙蓉厅举行订婚酒宴。\n\n";
    } else if (type == "birthday") {
        mesg = me->name() + "现在在醉仙楼芙蓉厅举行生辰寿宴。\n\n";
    } else if (type == "player") {
        mesg = me->name() + "现在在醉仙楼芙蓉厅宴请各路英雄豪杰。\n\n";
    }
    message("channel:chat", HIW "【江湖通告】" + mesg + NOR, users());
    return 1;
}

int do_order(string arg) {
    object me, env;
    object *oblist;
    string mesg;
    int idx;

    me = this_player();
    env = this_object();
    mesg = query("order_owner");
    if (mesg
        && (arg == "end")
        && (mesg == me->query("id"))) {
        mesg = "芙蓉厅的宴会结束了。\n\n";
        message("channel:chat", HIW "【江湖通告】" + mesg + NOR, users());

        delete("order_owner");
        delete("order_type");
        oblist = all_inventory(env);

        for (idx = 0; idx < sizeof(oblist); idx++) {
            if (!objectp(oblist[idx]))
                continue;
            if (userp(oblist[idx]))
                continue;
            destruct(oblist[idx]);
        }
        return 1;
